using Astraea.Application.Abstractions; using Astraea.Application.Retention; using Astraea.Application.Study; using Astraea.Domain; using Microsoft.EntityFrameworkCore;
namespace Astraea.Infrastructure;
public sealed class StudyLogService(AstraeaDbContext db,IUnitOfWork uow,IRetentionService retention):IStudyLogService { public async Task RecordAsync(Guid learnerId,StudyLogCreateDto r,CancellationToken ct){if(r.SelfRating is <1 or >5)throw new InvalidOperationException("Self-rating must be between 1 and 5.");var skill=await db.Skills.SingleOrDefaultAsync(x=>x.Id==r.SkillId&&x.LearnerId==learnerId&&!x.IsArchived,ct)??throw new KeyNotFoundException("Skill not found.");var(ease,interval)=retention.ApplyReview(skill.EaseFactor,skill.CurrentIntervalDays,r.SelfRating);skill.EaseFactor=ease;skill.CurrentIntervalDays=interval;skill.LastReviewedUtc=r.StudiedAtUtc.ToUniversalTime();skill.NextReviewDueDateUtc=skill.LastReviewedUtc.AddDays(interval);db.StudyLogs.Add(new StudyLog{SkillId=skill.Id,StudiedAtUtc=skill.LastReviewedUtc,SelfRating=r.SelfRating,Notes=r.Notes.Trim()});await uow.SaveChangesAsync(ct);} }
